// The pricing policy constructs its own details: two hard
// arrows from business logic into volatile infrastructure.
public class InvoiceService
{
    public void Issue(Order order)
    {
        var store = new SqlInvoiceStore(
            "Server=db;Database=billing;Trusted_Connection=True");
        var notifier = new SmtpNotifier("smtp.internal", 587);

        var invoice = Invoice.From(order);
        store.Insert(invoice);
        notifier.Send(order.CustomerEmail, invoice);
    }
}

// Swapping the database or the mail vendor edits this class:
// the policy changes whenever a detail changes.

modelExamples.after:
// The policy declares what it needs, in its own vocabulary.
// The details implement it — both arrows now point inward.
public interface IInvoiceStore
{
    void Add(Invoice invoice);
}

public interface ICustomerNotifier
{
    void InvoiceIssued(Invoice invoice);
}

public class InvoiceService
{
    private readonly IInvoiceStore _store;
    private readonly ICustomerNotifier _notifier;

    public InvoiceService(
        IInvoiceStore store, ICustomerNotifier notifier)
    {
        _store = store;
        _notifier = notifier;
    }

    public void Issue(Order order)
    {
        var invoice = Invoice.From(order);
        _store.Add(invoice);
        _notifier.InvoiceIssued(invoice);
    }
}

// At the program's edge, once:
// new InvoiceService(
//     new SqlInvoiceStore(cs), new SmtpNotifier(host, port));

