// There is an interface — but it leaks the technology through
// every signature. Callers still depend on SQL, in detail.
public interface IOrderData
{
    SqlConnection OpenConnection(string connectionString);
    DataTable RunQuery(SqlConnection connection, string sql);
    void Execute(SqlConnection connection, string insertSql);
}

// The "abstracted" caller, still speaking SQL:
public class OrderStatistics
{
    private readonly IOrderData _data;

    public OrderStatistics(IOrderData data) => _data = data;

    public int CountFor(string customerId)
    {
        using var connection =
            _data.OpenConnection(Config.OrdersDb);
        var rows = _data.RunQuery(connection,
            "SELECT * FROM Orders WHERE CustomerId = '"
                + customerId + "'");
        return rows.Rows.Count;
    }
}

modelExamples.after:
// A stable abstraction speaks the caller's language and hides
// the technology completely. Swap SQL for anything — nothing
// on this side of the arrow moves.
public interface IOrderArchive
{
    IReadOnlyList<Order> OrdersFor(string customerId);
}

public class OrderStatistics
{
    private readonly IOrderArchive _archive;

    public OrderStatistics(IOrderArchive archive) =>
        _archive = archive;

    public int CountFor(string customerId) =>
        _archive.OrdersFor(customerId).Count;
}

// SqlOrderArchive implements IOrderArchive at the edge and
// owns connections, SQL text, and escaping — all of it now
// invisible from the policy side.

