// One class, three responsibilities: computes pay, formats
// the payslip, and delivers it. Every dependent of PayrollRun
// changes when any one of the three changes.
public class PayrollRun
{
    public string RunFor(Employee employee)
    {
        // 1. Policy: compute the pay
        var gross = employee.HoursWorked * employee.HourlyRate;
        var tax = gross * TaxRateFor(employee);
        var net = gross - tax;

        // 2. Presentation: format the payslip
        var html = "<h1>Payslip</h1>"
            + $"<p>{employee.Name}: {net:C}</p>";

        // 3. Delivery: write it where the portal reads it
        File.WriteAllText(
            $"/var/portal/payslips/{employee.Id}.html", html);
        return html;
    }

    private static decimal TaxRateFor(Employee e) =>
        e.Country == "AU" ? 0.32m : 0.25m;
}

modelExamples.after:
// One sentence per class, no "and". The pay rules are the
// stable center; formatting and delivery point at them.
public class PayCalculator
{
    public Pay For(Employee employee)
    {
        var gross = employee.HoursWorked * employee.HourlyRate;
        var tax = gross * TaxRateFor(employee);
        return new Pay(gross, tax, gross - tax);
    }

    private static decimal TaxRateFor(Employee e) =>
        e.Country == "AU" ? 0.32m : 0.25m;
}

public class PayslipFormatter
{
    public string Html(Employee employee, Pay pay) =>
        "<h1>Payslip</h1>"
            + $"<p>{employee.Name}: {pay.Net:C}</p>";
}

public class PortalDelivery
{
    public void Publish(string employeeId, string html) =>
        File.WriteAllText(
            $"/var/portal/payslips/{employeeId}.html", html);
}

